var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(!EditorApplication.isPlaying||scene.path!="Assets/Scenes/CM_CrookedMortar_Production02.unity")throw new System.Exception("Production02 Play mode required");var docs="ArtSource/Blender/Architecture/CrookedMortar/Production02";var roots=scene.GetRootGameObjects();var baseline=new Newtonsoft.Json.Linq.JArray(Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(docs+"/CollisionBaseline.json")).Where(j=>(string)j["name"]!="Crooked Mortar Player").OrderBy(j=>(string)j["name"]));Physics.SyncTransforms();var actual=roots.SelectMany(g=>g.GetComponentsInChildren<Collider>()).Where(c=>!(c is CharacterController)).Select(c=>new{name=c.name,position=c.transform.position.ToString("F5"),size=c.bounds.size.ToString("F5")}).OrderBy(c=>c.name).ToArray();bool collisionsSame=Newtonsoft.Json.Linq.JToken.DeepEquals(baseline,Newtonsoft.Json.Linq.JArray.FromObject(actual));
