var temp=UnityEngine.SceneManagement.SceneManager.CreateScene("Production02 temporary geometry probes",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics3D));var ps=temp.GetPhysicsScene();var testMeshes=new System.Collections.Generic.List<Mesh>();
GameObject AddProbe(string rootName){var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};var list=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/BlightBloom/Art/Architecture/CrookedMortar/Production02/Models/"+rootName+".fbx").GetComponentsInChildren<MeshFilter>().Select(m=>new CombineInstance{mesh=m.sharedMesh,transform=m.transform.localToWorldMatrix}).ToArray();mesh.CombineMeshes(list,true,true);testMeshes.Add(mesh);var g=new GameObject("Isolated "+rootName);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,temp);g.AddComponent<MeshCollider>().sharedMesh=mesh;return g;}
