for(float x=-2.48f;x<9.5f;x+=.16f)for(float z=-2.83f;z<9.5f;z+=.16f){float high=float.NegativeInfinity;foreach(var tri in triangles){var a=new Vector2(tri.a.x,tri.a.z);var b=new Vector2(tri.b.x,tri.b.z);var c=new Vector2(tri.c.x,tri.c.z);var p=new Vector2(x,z);float cross=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(cross)<1e-8f)continue;float u=((b.y-c.y)*(p.x-c.x)+(c.x-b.x)*(p.y-c.y))/cross;float v=((c.y-a.y)*(p.x-c.x)+(a.x-c.x)*(p.y-c.y))/cross;float w=1-u-v;if(u>=.0001f&&v>=.0001f&&w>=.0001f)high=Mathf.Max(high,u*tri.a.y+v*tri.b.y+w*tri.c.y);}if(float.IsNegativeInfinity(high))continue;roofSamples++;if(!ps.Raycast(new Vector3(x,high+.4f,z),Vector3.down,out var h,.56f,~0,QueryTriggerInteraction.Ignore)||h.point.y<high-.015f||h.point.y>high+.14f)missedRoof.Add(new{x,z,expected=high,actual=h.point.y});}
