var report=new{passed=collisionsSame&&floorHoles==0&&ceilingHoles==0&&missedRoof.Count==0&&meshStats.All(m=>m.uv&&m.validUV&&m.validNormals),collisionsSame,colliderCount=actual.Length,floorSamples,floorHoles,ceilingHoles,roofSamples,roofMisses=missedRoof.Count,missedRoof,roomReports,renderers=meshStats.Length,triangles=meshStats.Sum(m=>m.triangles),badMeshAttributes=meshStats.Where(m=>!m.uv||!m.validUV||!m.validNormals).ToArray(),missingScripts=roots.SelectMany(g=>g.GetComponentsInChildren<Component>(true)).Count(c=>c==null),method="Temporary isolated physics scene tests only the new visible architecture/roof mesh surfaces, independently of inherited gameplay colliders; exact source carrier upper-envelope heights. All temporary probe objects removed."};System.IO.File.WriteAllText(docs+"/IntegrationGeometryValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return new{report.passed,report.collisionsSame,report.floorSamples,report.floorHoles,report.ceilingHoles,report.roofSamples,report.roofMisses,report.badMeshAttributes,report.missingScripts};
